import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";

import * as Pagination from "../../ui/pagination";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    Pagination.rootView<Message>({
      children: [
        Pagination.contentView<Message>({
          children: [
            Pagination.itemView<Message>({
              children: [Pagination.previousView<Message>({ href: "#" })],
            }),
            Pagination.itemView<Message>({
              children: [
                Pagination.linkView<Message>({
                  href: "#",
                  label: "Go to page 1",
                  children: ["1"],
                }),
              ],
            }),
            Pagination.itemView<Message>({
              children: [
                Pagination.linkView<Message>({
                  href: "#",
                  label: "Go to page 2",
                  active: true,
                  children: ["2"],
                }),
              ],
            }),
            Pagination.itemView<Message>({
              children: [
                Pagination.linkView<Message>({
                  href: "#",
                  label: "Go to page 3",
                  children: ["3"],
                }),
              ],
            }),
            Pagination.itemView<Message>({
              children: [Pagination.ellipsisView<Message>()],
            }),
            Pagination.itemView<Message>({
              children: [Pagination.nextView<Message>({ href: "#" })],
            }),
          ],
        }),
      ],
    })
);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as PaginationBasicExample from "./main";

describe("Pagination Basic example", () => {
  test("matches the shadcn Pagination basic example", () => {
    Scene.scene(
      {
        update: PaginationBasicExample.update,
        view: PaginationBasicExample.view,
      },
      Scene.with(PaginationBasicExample.init()[0]),
      Scene.expect(Scene.role("navigation", { name: "pagination" })).toExist(),
      Scene.expect(Scene.role("link", { name: "Go to page 2" })).toHaveAttr(
        "aria-current",
        "page"
      ),
      Scene.expect(Scene.role("link", { name: "Previous" })).toExist(),
      Scene.expect(Scene.role("link", { name: "Next" })).toExist(),
      Scene.expect(Scene.text("...")).not.toHaveHandler("click")
    );
  });
});
